def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split off pre-release (after '-')
        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        mmp = version_part.split('.')
        major = int(mmp[0])
        minor = int(mmp[1]) if len(mmp) > 1 else 0
        patch = int(mmp[2]) if len(mmp) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part is None:
            prerelease_ids = None
        else:
            prerelease_ids = prerelease_part.split('.')

        return (major, minor, patch, prerelease_ids)

    def prerelease_cmp_key(prerelease_ids):
        # Returns a tuple for comparison.
        # A version without pre-release (None) should sort after one with pre-release.
        if prerelease_ids is None:
            # No pre-release: sorts after any pre-release
            # Use (1,) to sort after (0, ...)
            return (1,)
        else:
            # Has pre-release: sorts before no pre-release
            # Convert each identifier: numeric ones as (0, int), non-numeric as (1, str)
            ids = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    ids.append((0, int(identifier)))
                else:
                    ids.append((1, identifier))
            return (0, tuple(ids))

    parsed = [(parse_version(v), i, v) for i, v in enumerate(versions)]

    def sort_key(item):
        (major, minor, patch, prerelease_ids), index, original = item
        return (major, minor, patch, prerelease_cmp_key(prerelease_ids), index)

    sorted_versions = sorted(parsed, key=sort_key)
    return [original for _, _, original in sorted_versions]

